// Hand-written Quarkus (JAX-RS) resource (never generated by gherkin-ai).
package com.acme.payments;

import jakarta.annotation.security.RolesAllowed;
import jakarta.inject.Inject;
import jakarta.validation.Valid;
import jakarta.ws.rs.*;
import jakarta.ws.rs.core.Response;
import java.net.URI;

@Path("/payments")
public class PaymentResource {

    @Inject
    PaymentRepository payments;

    @POST
    @RolesAllowed("teller")
    public Response initiate(@Valid InitiatePaymentRequest request) {
        if (payments.existsByReference(request.reference())) {
            throw new WebApplicationException("Duplicate payment reference", Response.Status.CONFLICT);
        }
        Payment payment = new Payment(request.reference(), request.amount(), PaymentStatus.PENDING);
        payments.persist(payment);
        return Response.created(URI.create("/payments/" + payment.id())).entity(payment).build();
    }

    @POST
    @Path("/{id}/settle")
    @RolesAllowed("teller")
    public Payment settle(@PathParam("id") String id) {
        Payment payment = payments.findByIdOptional(id).orElseThrow(() -> new NotFoundException("Payment not found"));
        if (payment.status != PaymentStatus.PENDING) {
            throw new PaymentStateException("Only pending payments can be settled");
        }
        payment.status = PaymentStatus.SETTLED;
        return payment;
    }
}
